import { CheckCircle2, X } from 'lucide-react'
import { DecisionCard, type Offer } from '@/components/DecisionCard'
import { ago, fmtDay, fmtTime, type ActivityItem, type Card, type State } from '@/lib/api'
import type { MapSelection } from '@/components/SupplyMap'

interface Props {
  state: State
  nowMs: number
  selection: MapSelection
  onClear: () => void
  fresh: Set<string>
  offer: Offer | null
  onOffer: (o: Offer | null) => void
  onChanged: () => void
  onHover: (routes: string[]) => void
  onDrawer: (card: Card, tab: 'evidence' | 'trail') => void
}

export function Rail(p: Props) {
  const { state, selection } = p
  const match = (c: Card) =>
    selection.routeId ? c.routes.includes(selection.routeId) : selection.nodeId ? c.supplier_id === selection.nodeId : true
  const mine = state.cards.filter((c) => c.status === 'open' && !c.routed_to_other && match(c))
  const withOther = state.cards.filter((c) => (c.routed_to_other && c.status === 'open') || c.status === 'escalated')
  const pinned = p.offer && !mine.some((c) => c.id === p.offer!.cardId) ? p.offer.card : null
  const filterName = selection.routeId
    ? `route ${selection.routeId}`
    : selection.nodeId
      ? state.map.nodes.find((n) => n.id === selection.nodeId)?.name
      : null

  const card = (c: Card) => (
    <DecisionCard
      key={c.id}
      card={c}
      nowMs={p.nowMs}
      isNew={p.fresh.has(c.id)}
      offer={p.offer}
      onOffer={p.onOffer}
      onChanged={p.onChanged}
      onHover={p.onHover}
      onDrawer={p.onDrawer}
    />
  )

  return (
    <div className="space-y-4">
      {filterName && (
        <button
          onClick={p.onClear}
          className="inline-flex cursor-pointer items-center gap-2 rounded-full bg-ink px-3.5 py-1.5 text-sm font-semibold text-white"
        >
          Showing {filterName} <X size={14} />
        </button>
      )}

      {pinned && card(pinned)}
      {mine.length > 0 ? (
        <>
          <h1 className="text-sm font-bold uppercase tracking-wide text-ink-3">
            Needs you · {mine.length}
          </h1>
          {mine.map(card)}
        </>
      ) : (
        !pinned && <Calm state={state} nowMs={p.nowMs} filtered={!!filterName} />
      )}

      {withOther.length > 0 && (
        <>
          <h2 className="pt-2 text-sm font-bold uppercase tracking-wide text-ink-3">With others · {withOther.length}</h2>
          {withOther.map(card)}
        </>
      )}

      <Activity items={state.activity} />
    </div>
  )
}

function Calm({ state, nowMs, filtered }: { state: State; nowMs: number; filtered: boolean }) {
  return (
    <section className="rounded-2xl border border-line p-6">
      <CheckCircle2 size={36} className="text-ok" />
      <h1 className="mt-3 text-[26px] font-extrabold leading-tight">
        {filtered ? 'Nothing open here.' : 'On track. Nothing needs you right now.'}
      </h1>
      <p className="mt-2 text-[15px] text-ink-2">
        Agents read {state.read_since_6} new files since 06:00 · last check {ago(state.last_check_at, nowMs)}
      </p>
    </section>
  )
}

function Activity({ items }: { items: ActivityItem[] }) {
  if (!items.length) return null
  return (
    <section className="pt-2">
      <h2 className="text-sm font-bold uppercase tracking-wide text-ink-3">Activity</h2>
      <ul className="mt-2 divide-y divide-line">
        {items.slice(0, 12).map((a, i) => (
          <li key={i} className="flex gap-3 py-2.5 text-[15px]">
            <span className="w-[72px] shrink-0 text-sm tabular-nums text-ink-3">
              {a.at ? `${fmtDay(a.at)} ${fmtTime(a.at)}` : ''}
            </span>
            <span className="min-w-0 text-ink-2">
              <span className="break-words">{a.text}</span>
              {a.detail && <span className="block text-sm text-ink-3">{a.detail}</span>}
            </span>
          </li>
        ))}
      </ul>
    </section>
  )
}
      let fallback: ReturnType<typeof setTimeout> | undefined;
      dc.onopen = () => {
        setStatus("live");
        dc.send(JSON.stringify({ type: "response.create" })); // assistant speaks first
      };
      dc.onmessage = (ev) => {
        const msg = JSON.parse(ev.data);
        if (msg.type === "input_audio_buffer.committed") {
          upsert({ who: "you", text: "…", id: msg.item_id });
        } else if (msg.type === "conversation.item.input_audio_transcription.completed") {
          if (msg.transcript?.trim()) upsert({ who: "you", text: msg.transcript.trim(), id: msg.item_id });
          else drop(msg.item_id);
        } else if (msg.type === "conversation.item.input_audio_transcription.failed") {
          drop(msg.item_id);
        } else if (msg.type === "response.output_audio_transcript.delta" || msg.type === "response.audio_transcript.delta") {
          setLines((prev) => {
            const i = prev.findIndex((p) => p.id === msg.item_id);
            if (i < 0) return [...prev, { who: "assistant" as const, text: msg.delta, id: msg.item_id }].slice(-12);
            const next = [...prev];
            next[i] = { ...next[i], text: next[i].text + msg.delta };
            return next;
          });
        } else if (msg.type === "response.output_audio_transcript.done" || msg.type === "response.audio_transcript.done") {
          upsert({ who: "assistant", text: msg.transcript, id: msg.item_id });
        } else if (msg.type === "response.function_call_arguments.done" && msg.name === "record_decision") {
          const args = JSON.parse(msg.arguments || "{}");
          const action = DECISION_TO_ACTION[args.decision] ?? "edit";
          const note = [`voice: ${args.decision}`, args.note].filter(Boolean).join(" · ");
          onAction(card.id, action, note);
          add({ who: "system", text: `Decision recorded: ${args.decision}` });
          dc.send(JSON.stringify({
            type: "conversation.item.create",
            item: { type: "function_call_output", call_id: msg.call_id, output: JSON.stringify({ ok: true }) },
          }));
          dc.send(JSON.stringify({ type: "response.create" }));
          decided = true;
        } else if (msg.type === "response.function_call_arguments.done") {
          // Other tools run on the server; relay the result back to the model.
          const args = JSON.parse(msg.arguments || "{}");
          add({ who: "system", text: `Running ${msg.name}…` });
          fetch(`/api/cards/${encodeURIComponent(card.id)}/tool`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ name: msg.name, arguments: args }),
          })
            .then((r) => r.json())
            .catch((e) => ({ ok: false, error: String(e) }))
            .then((out) => {
              if (msg.name === "send_supplier_email" && out.ok) add({ who: "system", text: `Email sent to ${out.sent_to}` });
              if (msg.name === "escalate" && out.ok) add({ who: "system", text: "Escalated" });
              if (out.ok && msg.name !== "get_card_details") decided = true;
              dc.send(JSON.stringify({
                type: "conversation.item.create",
                item: { type: "function_call_output", call_id: msg.call_id, output: JSON.stringify(out) },
              }));
              dc.send(JSON.stringify({ type: "response.create" }));
            });
        } else if (msg.type === "response.done" && decided && !closing) {
          // Hang up once the goodbye has finished playing, not on a fixed timer.
          closing = true;
          fallback = setTimeout(hangUp, 20000);
        } else if (msg.type === "output_audio_buffer.stopped" && closing) {
          clearTimeout(fallback);
          setTimeout(hangUp, 800);
        } else if (msg.type === "error") {
          add({ who: "system", text: `Error: ${msg.error?.message ?? "unknown"}` });
        }
      };

      const offer = await peer.createOffer();
      await peer.setLocalDescription(offer);
      const sdp = await fetch("https://api.openai.com/v1/realtime/calls", {
        method: "POST",
        body: offer.sdp,
        headers: { Authorization: `Bearer ${client_secret}`, "Content-Type": "application/sdp" },
      });
      if (!sdp.ok) throw new Error(await sdp.text());
      await peer.setRemoteDescription({ type: "answer", sdp: await sdp.text() });
    } catch (e) {
      add({ who: "system", text: `Could not start: ${(e as Error).message.slice(0, 200)}` });
      setStatus("error");
      pc.current?.close();
    }
  }

  if (autoStart && !started.current) void start();

  const live = status === "connecting" || status === "live";
  if (ringing && !live) {
    return (
      <div className="rounded-lg border-2 border-danger bg-danger/5 p-4 text-center">
        <div className="text-xs font-semibold uppercase tracking-wide text-danger">Incoming launch alert</div>
        <div className="mt-1 text-base font-semibold">{card.title}</div>
        <div className="mt-4 flex justify-center gap-3">
          <button
            className="rounded-full bg-emerald-600 px-6 py-3 text-base font-semibold text-white"
            onClick={() => {
              setRinging(false);
              history.replaceState(null, "", `/?card=${encodeURIComponent(card.id)}`);
              void start();
            }}
          >
            Answer
          </button>
          <button
            className="rounded-full border border-slate-300 px-6 py-3 text-base"
            onClick={() => {
              setRinging(false);
              history.replaceState(null, "", `/?card=${encodeURIComponent(card.id)}`);
            }}
          >
            Later
          </button>
        </div>
      </div>
    );
  }
  return (
    <div className="rounded-md border border-slate-200 p-3">
      <div className="flex flex-wrap items-center gap-3">
        {!live ? (
          <button className="rounded-md bg-accent px-3 py-1.5 text-sm font-medium text-white" onClick={start}>
            Talk to the assistant
          </button>
        ) : (
          <button className="rounded-md border border-danger px-3 py-1.5 text-sm font-medium text-danger" onClick={hangUp}>
            Hang up
          </button>
        )}
        {pushSupported() && !live && (
          <>
            <button className="rounded-md border border-slate-300 px-3 py-1.5 text-sm" onClick={async () => setInfo(await enableAlerts())}>
              Enable call alerts on this device
            </button>
            <button className="rounded-md border border-slate-300 px-3 py-1.5 text-sm" onClick={async () => setInfo(await sendTestAlert(card.id))}>
              Send test alert
            </button>
          </>
        )}
        <span className="text-xs text-slate-500">
          {info && <span className="mr-2">{info}</span>}
          {status === "connecting" && "Connecting…"}
          {status === "live" && "Live: speak normally"}
          {status === "ended" && "Call ended"}
          {status === "error" && "Call failed"}
        </span>
      </div>
      {lines.length > 0 && (
        <ul className="mt-3 space-y-1 text-sm">
          {lines.map((l, i) => (
            <li
              key={l.id ?? i}
              className={`break-words ${l.who === "you" ? "text-right text-slate-500" : l.who === "system" ? "text-xs text-accent" : ""}`}
            >
              {l.who !== "system" && (
                <span className="font-medium">{l.who === "assistant" ? "Assistant: " : "You: "}</span>
              )}
              {l.text}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
