    ("  const trust = (m: 'allow_always' | 'ask') =>",
     """  // The voice assistant records a spoken decision through the same endpoints as the buttons.
  const voiceDecision = async (decision: string, note?: string) => {
    if (decision === 'approve') await post(`/api/cards/${card.id}/approve`, { option: 0 })
    else if (decision === 'escalate') await post(`/api/cards/${card.id}/escalate`, { note })
    else await post(`/api/cards/${card.id}/dismiss`, { note })
    onChanged()
  }
  const trust = (m: 'allow_always' | 'ask') =>"""),
    ("""      {other && (
        <div className="mt-4 flex items-start gap-2""",
     """      {card.status !== 'open' && !other && (
        <p className="mt-3 inline-flex items-center gap-1.5 rounded-full bg-panel px-3 py-1 text-sm font-semibold text-ink-2 ring-1 ring-line">
          <Check size={14} /> {card.status === 'sent' ? 'Sent' : card.status[0].toUpperCase() + card.status.slice(1)}
          {card.ui?.at ? ` · ${fmtDay(card.ui.at)} ${fmtTime(card.ui.at)}` : ''}
        </p>
      )}

      {card.action_status?.status === 'replied' && (
        <div className="mt-4 rounded-xl border border-line bg-panel p-4">
          <div className="flex items-center gap-2 text-sm font-semibold text-ink-2">
