        <div className="mt-4 flex items-start gap-2"""),
    ("""      <div className="mt-4 flex gap-5 border-t border-line pt-3""",
     """      {!other && (
        <div className="mt-4">
          <VoiceCall card={card} onDecision={voiceDecision} onChanged={onChanged} />
        </div>
      )}

      <div className="mt-4 flex gap-5 border-t border-line pt-3"""),
])

edit("web/src/components/Rail.tsx", [
    ("import { CheckCircle2, X } from 'lucide-react'", "import { CheckCircle2, X } from 'lucide-react'\nimport { useState } from 'react'"),
    ("export function Rail(p: Props) {\n  const { state, selection } = p\n",
     "const DECIDED = new Set(['approved', 'sent', 'dismissed', 'handled'])\n\nexport function Rail(p: Props) {\n  const { state, selection } = p\n  const [reopened, setReopened] = useState<string | null>(null)\n"),
    ("  const pinned =", "  const decided = state.cards.filter((c) => DECIDED.has(c.status))\n  const pinned ="),
    ("""      <Activity items={state.activity} />""",
     """      {decided.length > 0 && (
        <details
          className="pt-2"
          open={decided.some((c) => c.action_status?.status === 'replied' || c.id === reopened)}
        >
          <summary className="cursor-pointer text-sm font-bold uppercase tracking-wide text-ink-3">
            Decided · {decided.length}
          </summary>
          <ul className="mt-2 space-y-3">
            {decided.map((c) => (
              <li key={c.id}>
                {reopened === c.id ? (
                  card(c)
                ) : (
                  <button
                    onClick={() => setReopened(c.id)}
                    className="flex w-full cursor-pointer items-center justify-between gap-3 rounded-lg px-3 py-2 text-left text-[15px] text-ink-2 hover:bg-panel"
                  >
                    <span className="font-medium">{c.headline}</span>
                    <span className="shrink-0 text-sm text-ink-3">
                      {c.action_status?.status === 'replied' ? 'replied' : c.status}
                    </span>
                  </button>
                )}
              </li>
            ))}
          </ul>
        </details>
      )}

      <Activity items={state.activity} />"""),
])

